/* 纯逻辑，可独立测试；所有时间单位为毫秒。 */
const Core = (()=>{
 const durations=[420000,420000,240000,120000];
 function plan(words,records,now){const due=words.filter(w=>records[w.id]&&records[w.id].due<=now).sort((a,b)=>records[a.id].due-records[b.id].due).slice(0,20).map(w=>({id:w.id,kind:'review'}));const fresh=words.filter(w=>!records[w.id]).slice(0,10).map(w=>({id:w.id,kind:'new'}));const extra=fresh.length?[]:words.filter(w=>!due.some(d=>d.id===w.id)).slice(0,10).map(w=>({id:w.id,kind:'practice'}));return [...due,...fresh,...extra];}
 function session(words,db,now=Date.now()){return {id:now+'-'+Math.random().toString(36).slice(2,7),lesson:db.round%3,stage:0,elapsed:[0,0,0,0],running:false,finished:false,queue:plan(words.filter(w=>w.id<(db.wordLimit||4000)),db.words,now),index:0,revealed:false,answers:{},checked:{},graded:{},clozeIndex:0,audioTime:0,createdAt:now};}
 function advance(s,delta){if(!s.running||s.finished||!Number.isFinite(delta))return;s.elapsed[s.stage]=Math.min(Number.MAX_SAFE_INTEGER,s.elapsed[s.stage]+Math.max(0,delta));}
 function schedule(old,grade,now){let reps=old?.reps||0;reps=grade===0?0:reps+1;const days=grade===0?0:grade===1?1:[1,3,7,14,30,60][Math.min(reps-1,5)];return {reps,due:now+(grade===0?600000:days*86400000),lastGrade:grade,updatedAt:now};}
 function normalized(t){return t.toLowerCase().replace(/[’]/g,"'").replace(/[^a-z0-9'\s]/g,' ').trim().split(/\s+/).filter(Boolean);}
 function score(actual,expected){const a=normalized(actual),b=normalized(expected),dp=Array.from({length:a.length+1},()=>Array(b.length+1).fill(0));for(let i=1;i<=a.length;i++)for(let j=1;j<=b.length;j++)dp[i][j]=a[i-1]===b[j-1]?dp[i-1][j-1]+1:Math.max(dp[i-1][j],dp[i][j-1]);return Math.round(100*dp[a.length][b.length]/Math.max(a.length,b.length,1));}
 function validate(db,wordCount=typeof WORDS!=='undefined'?WORDS.length:6000){if(!db||db.version!==1||!Number.isInteger(db.round)||db.round<0||!db.words||!Array.isArray(db.history)||db.history.length>500)throw Error('备份格式无效');if(Object.keys(db.words).some(k=>!/^\d+$/.test(k)||Number(k)>=wordCount||!Number.isFinite(db.words[k]?.due)||!Number.isInteger(db.words[k]?.reps)||db.words[k].reps<0))throw Error('词汇记录无效');const s=db.session;if(s){if(!Number.isInteger(s.lesson)||s.lesson<0||s.lesson>2||!Number.isInteger(s.stage)||s.stage<0||s.stage>3||!Array.isArray(s.elapsed)||s.elapsed.length!==4||s.elapsed.some((v,i)=>!Number.isFinite(v)||v<0||v>Number.MAX_SAFE_INTEGER)||!Array.isArray(s.queue)||s.queue.length>40||s.queue.some(x=>!Number.isInteger(x.id)||x.id<0||x.id>=wordCount||!['review','new','practice'].includes(x.kind))||!Number.isInteger(s.index)||s.index<0||s.index>s.queue.length||!s.answers||typeof s.answers!=='object'||!s.checked||!s.graded||!Number.isFinite(s.audioTime)||s.audioTime<0||s.audioTime>3600||!Number.isInteger(s.clozeIndex)||s.clozeIndex<0||s.clozeIndex>3)throw Error('训练状态无效');for(const v of Object.values(s.answers))if(!['string','boolean'].includes(typeof v)||typeof v==='string'&&v.length>20000)throw Error('答案无效');s.running=false;}if(db.wordLimit!==undefined&&(!Number.isInteger(db.wordLimit)||db.wordLimit<1||db.wordLimit>wordCount))throw Error('词库范围无效');return db;}
 return {durations,plan,session,advance,schedule,score,validate};
})();
if(typeof module!=='undefined')module.exports=Core;

